target.css:
:root {
  --ink: #25313a;
  --paper: #fffaf1;
  --line: #d9cdbd;
  --terracotta: #ce694d;
  --ochre: #e5ad48;
  --sage: #6e8872;
}

.paint-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-left: 6px solid var(--terracotta);
  border-radius: 14px;
}

.paint-card header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 14px 16px 12px;
}

.title-block {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--terracotta);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.batch {
  padding: 5px 8px;
  color: var(--sage);
  background: var(--paper);
  border: 1px solid var(--sage);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.recipe {
  display: grid;
  grid-template-columns: 128px 1fr;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.paint-swatch {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 7px;
  margin: 0;
  padding: 14px 16px;
  background: var(--ochre);
}

.drop {
  display: block;
  width: 38px;
  height: 38px;
  background: var(--terracotta);
  border: 3px solid var(--paper);
  border-radius: 50% 50% 50% 8px;
  transform: rotate(-45deg);
}

figcaption {
  font-size: 11px;
  line-height: 1.25;
}

.mix-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin: 0;
  padding: 12px 16px;
  list-style: none;
}

.mix-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--line);
  font-size: 14px;
}

.mix-list li:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.mix-list b {
  color: var(--terracotta);
  font-size: 12px;
}

footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
}

footer p {
  margin: 0;
  font-size: 12px;
}

button {
  padding: 6px 10px;
  color: var(--paper);
  background: var(--sage);
  border: 0;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}

